let rows = [];
let totalTaxRate = 0;

// Iterate over the rate_details in the input data
$input.first().json.rate_details.forEach(tax => {
  // Push each row with the necessary columns (Tax Agency, Tax Rate, Overall Tax Rate)
  rows.push([
    tax.tax_agency,  // Tax Agency
    tax.tax_rate,    // Tax Rate
    tax.tax_rate     // Overall Tax Rate (same for each agency in this case)
  ]);

  // Accumulate the overall tax rate for the total
  totalTaxRate += tax.tax_rate;
});

// Add the total row at the end
rows.push([
  "Total",               // Label for Total
  "",                    // Empty field for Tax Rate
  totalTaxRate           // Sum of all Tax Rates
]);

// Return the rows so they can be used by the next node
return [{ json: { rows } }];
